    "lacunas": [
      "As precedências e os requisitos de disponibilidade da ficha relacional d_aa83 não estão fornecidos; não é possível determinar como a disponibilidade do substituto afeta o término final."
    ],
    "motivo": "A disponibilidade do substituto e as durações das atividades não bastam para calcular o término sem as relações de precedência e disponibilidade.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
